function compileAuditPacket(parts) {
  if (!parts || typeof parts !== 'object' || Array.isArray(parts)) throw new TypeError('parts must be an object');
  const names = ['actor', 'evidence', 'policy', 'display'];
  for (const name of names) {
    if (!parts[name] || typeof parts[name] !== 'object' || typeof parts[name].exportData !== 'function') {
      throw new TypeError(name + ' must expose exportData');
    }
  }

  const copy = (value, name) => {
    if (value === undefined) throw new TypeError(name + ' returned undefined');
    let encoded;
    try {
      encoded = JSON.stringify(value);
    } catch (error) {
      throw new TypeError(name + ' returned non-JSON data');
    }
    if (encoded === undefined) throw new TypeError(name + ' returned non-JSON data');
    return JSON.parse(encoded);
  };

  const actorData = copy(parts.actor.exportData(), 'actor');
  const evidenceData = copy(parts.evidence.exportData(), 'evidence');
  const policyData = copy(parts.policy.exportData(), 'policy');
  const displayData = copy(parts.display, 'display');
  return { actorData, evidenceData, policyData, displayData };
}

module.exports = { compileAuditPacket };

