'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['compileAuditPacket']);
const { compileAuditPacket } = api;

const order = [];
const owned = {
  actor: { name: 'Ada', nested: { roles: ['admin'] } },
  evidence: [{ id: 1 }],
  policy: 'P-1',
  display: null
};
function component(name) {
  return {
    exportData() {
      assert.strictEqual(this, parts[name]);
      order.push(name);
      return owned[name];
    }
  };
}
const parts = {
  actor: component('actor'),
  evidence: component('evidence'),
  policy: component('policy'),
  display: component('display')
};
const packet = compileAuditPacket(parts);
assert.deepStrictEqual(order, ['actor', 'evidence', 'policy', 'display']);
assert.deepStrictEqual(packet, {
  actorData: owned.actor,
  evidenceData: owned.evidence,
  policyData: 'P-1',
  displayData: null
});
assert.notStrictEqual(packet.actorData, owned.actor);
assert.notStrictEqual(packet.actorData.nested, owned.actor.nested);
assert.notStrictEqual(packet.actorData.nested.roles, owned.actor.nested.roles);
assert.notStrictEqual(packet.evidenceData, owned.evidence);
packet.actorData.nested.roles.push('leak');
packet.evidenceData[0].id = 99;
assert.deepStrictEqual(owned.actor.nested.roles, ['admin']);
assert.strictEqual(owned.evidence[0].id, 1);

for (const malformed of [
  null,
  [],
  {},
  { actor: {}, evidence: { exportData() {} }, policy: { exportData() {} }, display: { exportData() {} } },
  { actor: { exportData() {} }, evidence: { exportData() {} }, policy: { exportData() {} }, display: { exportData() {} }, extra: true }
]) {
  assert.throws(() => compileAuditPacket(malformed), TypeError);
}

const base = value => ({ exportData() { return value; } });
assert.throws(() => compileAuditPacket({
  actor: base(undefined), evidence: base(1), policy: base(2), display: base(3)
}), TypeError);
const cyclic = {};
cyclic.self = cyclic;
assert.throws(() => compileAuditPacket({
  actor: base(cyclic), evidence: base(1), policy: base(2), display: base(3)
}));
assert.throws(() => compileAuditPacket({
  actor: base(1n), evidence: base(1), policy: base(2), display: base(3)
}));

const calls = [];
const sentinel = new Error('export failed');
assert.throws(() => compileAuditPacket({
  actor: { exportData() { calls.push('actor'); return {}; } },
  evidence: { exportData() { calls.push('evidence'); throw sentinel; } },
  policy: { exportData() { calls.push('policy'); return {}; } },
  display: { exportData() { calls.push('display'); return {}; } }
}), error => error === sentinel);
assert.deepStrictEqual(calls, ['actor', 'evidence']);

